/* ===== CART ===== */
const ckey=c=>c.pid+'|'+c.variant;
function couponDisc(sub){const c=D().coupons.find(x=>x.code===S.coupon);if(!c||sub<(c.min||0))return 0;return c.type==='flat'?Math.min(c.value,sub):Math.min(c.max||1e9,Math.round(sub*c.value/100))}
V.cart=()=>{const gs=cartGroups(),saved=S.cart.filter(c=>c.saved),sub=gs.reduce((a,g)=>a+g.sub,0),disc=couponDisc(sub);
 if(!gs.length&&!saved.length)return `<div class="stack"><h1>${t('Your cart')}</h1>${empty('🛒','Your cart is empty','Add items from nearby shops to get started.','<a class="btn p" href="#home">'+t('Start shopping')+'</a>')}</div>`;
 const line=l=>{const p=l.p,op=offerPrice(p);return `<div class="row" style="align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border)">${art(p.emoji,p.hue,'mini')}<div class="grow"><a href="#prod-${p.id}" class="bold">${esc(nm(p.name))}</a><div class="xs muted">${esc(p.unit)}${l.variant?' · '+esc(l.variant):''}</div><div class="row between" style="margin-top:6px"><div class="stepper"><button data-act="cq" data-k="${esc(ckey(l))}" data-d="-1" aria-label="${t('Decrease')}">−</button><b>${l.qty}</b><button data-act="cq" data-k="${esc(ckey(l))}" data-d="1" aria-label="${t('Increase')}">+</button></div><b class="price">${inr(op*l.qty)}</b></div><div class="row"><button class="btn t sm" data-act="csave" data-k="${esc(ckey(l))}">${t('Save for later')}</button><button class="btn t sm" data-act="crem" data-k="${esc(ckey(l))}">${ic('trash',14)} ${t('Remove')}</button></div></div></div>`};
 return `<div class="stack-lg"><h1>${t('Your cart')}</h1>${gs.length>1?alertBox('info',`<b>${t('Your order will be split into')} ${gs.length} ${t('shops')}</b>. ${t('Each shop prepares and delivers its own order. One checkout, separate order IDs.')}`,'layers'):''}
 <div class="cols2"><div class="stack">${gs.map(g=>`<div class="card pad"><a class="row" href="#biz-${g.bid}">${art(g.b.emoji,g.b.hue,'mini')}<div class="grow"><b>${esc(nm(g.b.name))}</b><div class="xs muted">${esc(areaName(g.b.area))} · ${dist(g.b).toFixed(1)} km</div></div>${ic('cr')}</a>${g.lines.map(line).join('')}<div class="row between small" style="margin-top:8px"><span>${t('Shop subtotal')}</span><b>${inr(g.sub)}</b></div>${g.sub<g.b.del.min?`<div class="small" style="color:var(--warning);margin-top:4px">${ic('alert',14)} ${t('Minimum order for delivery')} ${inr(g.b.del.min)}. ${t('Add')} ${inr(g.b.del.min-g.sub)} ${t('more or choose self-pickup.')}</div>`:''}</div>`).join('')}
 ${saved.length?`<div class="card pad"><h3>${t('Saved for later')}</h3>${saved.map(c=>{const p=prod(c.pid);return `<div class="row" style="padding:8px 0">${art(p.emoji,p.hue,'mini')}<div class="grow"><b>${esc(nm(p.name))}</b><div class="xs muted">${inr(p.price)}</div></div><button class="btn o sm" data-act="cmove" data-k="${esc(ckey(c))}">${t('Move to cart')}</button><button class="iconbtn" data-act="crem" data-k="${esc(ckey(c))}" aria-label="${t('Remove')}">${ic('trash',18)}</button></div>`}).join('')}</div>`:''}</div>
 <div class="stack"><div class="card pad stack"><h3>${t('Offers & coupon')}</h3><form data-form="coupon" class="row"><input class="input" name="code" value="${esc(S.coupon)}" placeholder="${t('Enter coupon code')}" aria-label="${t('Coupon code')}" style="text-transform:uppercase"><button class="btn o">${t('Apply')}</button></form>${S.coupon&&!disc?alertBox('warn',t('Coupon not valid for this cart.')):disc?alertBox('ok',`<b>${S.coupon}</b> ${t('applied')}: −${inr(disc)}`):`<div class="chips">${D().coupons.map(c=>`<button class="chip" data-act="usecoupon" data-v="${c.code}">${c.code}</button>`).join('')}</div>`}</div>
 <div class="card pad stack"><h3>${t('Price details')}</h3><dl class="kv"><dt>${t('Items total')}</dt><dd>${inr(sub)}</dd>${disc?`<dt>${t('Coupon discount')}</dt><dd style="color:var(--success)">−${inr(disc)}</dd>`:''}<dt>${t('Delivery charges')}</dt><dd>${t('At checkout')}</dd><dt>${t('Platform fee')} (${gs.length}×)</dt><dd>${inr(D().cfg.platformFee*gs.length)}</dd><dt>${t('Taxes (GST)')}</dt><dd>${t('Included')}</dd></dl><div class="divider"></div><div class="row between"><b>${t('Estimated total')}</b><b class="price">${inr(sub-disc+D().cfg.platformFee*gs.length)}</b></div><a class="btn p block ${gs.length?'':'disabled'}" href="#checkout">${t('Proceed to checkout')}</a></div></div></div></div>`};
A.cq=el=>{const c=S.cart.find(x=>ckey(x)===el.dataset.k),p=prod(c.pid);c.qty+=+el.dataset.d;if(c.qty<1)S.cart=S.cart.filter(x=>x!==c);else if(c.qty>Math.min(10,p.stock)){c.qty=Math.min(10,p.stock);toast(t('Max available reached'),'info')}save();render(true)};
A.crem=el=>{S.cart=S.cart.filter(x=>ckey(x)!==el.dataset.k);save();render(true)};
A.csave=el=>{S.cart.find(x=>ckey(x)===el.dataset.k).saved=true;save();render(true);toast(t('Saved for later'),'bookmark')};
A.cmove=el=>{S.cart.find(x=>ckey(x)===el.dataset.k).saved=false;save();render(true)};
A.usecoupon=el=>{S.coupon=el.dataset.v;save();render(true)};
F.coupon=d=>{S.coupon=(d.code||'').trim().toUpperCase();save();render(true)};
/* ===== CHECKOUT ===== */
function coInit(){const gs=cartGroups();UI.co=UI.co||{mode:{},pay:'upi'};gs.forEach(g=>{if(!UI.co.mode[g.bid]){const di=delivInfo(g.b);UI.co.mode[g.bid]=di.ok?'delivery':'pickup'}})}
function coCalc(){const gs=cartGroups(),sub=gs.reduce((a,g)=>a+g.sub,0),disc=couponDisc(sub);return gs.map(g=>{const mode=UI.co.mode[g.bid]||'delivery',di=delivInfo(g.b),fee=mode==='delivery'?di.fee:0,d=sub?Math.round(disc*g.sub/sub):0;const issues=[];if(mode==='delivery'&&!di.ok)issues.push('range');if(mode==='delivery'&&g.sub<g.b.del.min)issues.push('min');if(mode==='pickup'&&!g.b.del.pickup)issues.push('nopickup');if(g.b.status!=='approved')issues.push('closed');return{...g,mode,di,fee,disc:d,plat:D().cfg.platformFee,total:g.sub-d+fee+D().cfg.platformFee,issues}})}
V.checkout=()=>{if(!S.user)return `<div class="stack"><h1>${t('Checkout')}</h1>${empty('🔐','Log in to place your order','We need your mobile number to confirm delivery.','<a class="btn p" href="#login" data-act="loginNext">'+t('Log in / Sign up')+'</a>')}</div>`;
 if(!cartGroups().length)return `<div class="stack"><h1>${t('Checkout')}</h1>${empty('🛒','Your cart is empty','Add items to continue.','<a class="btn p" href="#home">'+t('Start shopping')+'</a>')}</div>`;
 coInit();const cs=coCalc(),total=cs.reduce((a,c)=>a+c.total,0),a=S.addrs.find(x=>x.id===S.selAddr),blocked=cs.some(c=>c.issues.length)||!a&&cs.some(c=>c.mode==='delivery');
 const anyDel=cs.some(c=>c.mode==='delivery');
 const pays=[['upi','UPI','📲','Google Pay, PhonePe, Paytm'],['card','Card','💳','Debit / credit card'],['nb','Net banking','🏦','All major banks'],['wallet','Wallet','👛','Paytm, Amazon Pay'],['cod',cs.every(c=>c.mode==='pickup')?'Pay at pickup':'Cash on delivery','💵','Pay when you receive']].filter(p=>p[0]==='cod'?D().cfg.cod:D().cfg.online);
 return `<div class="stack-lg"><h1>${t('Checkout')}</h1><div class="cols2"><div class="stack">
 <div class="card pad stack"><div class="row between"><h3>${t('Delivery address')}</h3><button class="btn t sm" data-act="addrPick">${t('Change')}</button></div>${a?`<div class="row" style="align-items:flex-start">${ic('pin',22)}<div class="grow"><b>${esc(a.label)}</b> · ${esc(a.name)}<div class="small t2">${esc(a.line)}, ${esc(a.landmark)}, ${esc(areaName(a.area))}, ${esc(a.pin)}</div></div></div>`:`<button class="btn o" data-act="addrEdit" data-id="">${t('Add address')}</button>`}</div>
 ${cs.map(c=>`<div class="card pad stack"><div class="row"><b class="grow">${esc(nm(c.b.name))}</b><span class="badge neu">${c.lines.length} ${t('items')}</span></div><div class="grid g2"><label class="chip ${c.mode==='delivery'?'on':''}" style="justify-content:center"><input class="sr" type="radio" name="m_${c.bid}" ${c.mode==='delivery'?'checked':''} data-chg="mode" data-b="${c.bid}" data-v="delivery">${ic('truck',16)} ${t('Home delivery')}</label><label class="chip ${c.mode==='pickup'?'on':''}" style="justify-content:center;${c.b.del.pickup?'':'opacity:.5'}"><input class="sr" type="radio" name="m_${c.bid}" ${c.mode==='pickup'?'checked':''} ${c.b.del.pickup?'':'disabled'} data-chg="mode" data-b="${c.bid}" data-v="pickup">${ic('store',16)} ${t('Self-pickup')}</label></div>
  ${c.mode==='delivery'?(c.di.ok?`<div class="small">${ic('truck',14)} ${c.di.d.toFixed(1)} km · ${t('Delivery')} <b>${c.fee?inr(c.fee):t('Free')}</b> · ${c.b.del.mode==='self'?t('by shop'):t('by ApnaTown rider')}</div>`:alertBox('warn',`<b>${t('Out of delivery range')}</b> (${c.di.d.toFixed(1)} km > ${c.b.del.radius} km). ${t('Choose self-pickup or another address.')}`,'pin')):`<div class="small">${ic('store',14)} ${esc(c.b.addr)} · ${esc(c.b.del.note)}</div>`}
  ${c.issues.includes('min')?alertBox('warn',`${t('Minimum order for delivery')} ${inr(c.b.del.min)}`):''}${c.lines.map(l=>`<div class="row between small"><span>${esc(nm(l.p.name))} × ${l.qty}</span><span>${inr(offerPrice(l.p)*l.qty)}</span></div>`).join('')}<div class="divider"></div><dl class="kv"><dt>${t('Shop subtotal')}</dt><dd>${inr(c.sub)}</dd>${c.disc?`<dt>${t('Coupon')}</dt><dd style="color:var(--success)">−${inr(c.disc)}</dd>`:''}<dt>${t('Delivery')}</dt><dd>${inr(c.fee)}</dd><dt>${t('Platform fee')}</dt><dd>${inr(c.plat)}</dd><dt><b>${t('Order total')}</b></dt><dd><b>${inr(c.total)}</b></dd></dl></div>`).join('')}
 <div class="card pad stack"><h3>${t('Payment')}</h3><div role="radiogroup" class="stack" style="gap:8px">${pays.map(p=>`<label class="card pad row" style="${UI.co.pay===p[0]?'border-color:var(--primary);background:var(--primary-soft)':''}"><input type="radio" name="pay" ${UI.co.pay===p[0]?'checked':''} data-chg="pay" data-v="${p[0]}" style="accent-color:var(--primary);width:20px;height:20px"><span style="font-size:1.4rem">${p[2]}</span><span class="grow"><b>${t(p[1])}</b><div class="xs muted">${t(p[3])}</div></span></label>`).join('')}</div></div></div>
 <div class="stack"><div class="card pad stack sticky-cta"><div class="row between"><span>${cs.length>1?t('Total for')+' '+cs.length+' '+t('orders'):t('Total')}</span><b class="price" style="font-size:1.4rem">${inr(total)}</b></div>${cs.length>1?`<div class="xs muted">${t('You will get a separate order ID for each shop.')}</div>`:''}<button class="btn p block" data-act="place" ${blocked?'disabled':''}>${UI.co.pay==='cod'?t('Place order'):t('Pay')+' '+inr(total)}</button>${blocked?`<div class="small" style="color:var(--error)">${t('Fix the items marked above to continue.')}</div>`:''}</div></div></div></div>`};
CH.mode=el=>{UI.co.mode[el.dataset.b]=el.dataset.v;render(true)};CH.pay=el=>{UI.co.pay=el.dataset.v;render(true)};
function newOrderId(){S.oc=(S.oc||10250)+1;return 'AT'+S.oc}
function createOrders(){const cs=coCalc(),ids=[];cs.forEach(c=>{const a=S.addrs.find(x=>x.id===S.selAddr);const o={id:newOrderId(),uid:'u1',bid:c.bid,mode:c.mode,items:c.lines.map(l=>({pid:l.pid,name:l.p.name,price:offerPrice(l.p),qty:l.qty,variant:l.variant,emoji:l.p.emoji})),subtotal:c.sub,delivery:c.fee,fee:c.plat,discount:c.disc,pay:{method:UI.co.pay==='cod'?(c.mode==='pickup'?'Pay at pickup':'COD'):UI.co.pay.toUpperCase(),status:UI.co.pay==='cod'?'pending':'paid'},status:'placed',ts:Date.now(),history:[{s:'placed',ts:Date.now()}],otp:String(1000+Math.floor(Math.random()*9000)),pickupCode:String(1000+Math.floor(Math.random()*9000)),addr:c.mode==='delivery'&&a?`${a.label}: ${a.line}, ${a.landmark}, ${areaName(a.area)} ${a.pin}`:'',addrPos:c.mode==='delivery'&&a?{lat:a.lat,lng:a.lng}:null,riderId:null,cust:S.user.name,phone:S.user.phone};
 D().orders.unshift(o);ids.push(o.id);notify('vendor','New order '+o.id,o.cust+' · '+inr(orderTotal(o)),'vorder-'+o.id,'order');c.lines.forEach(l=>{const p=prod(l.pid);p.stock=Math.max(0,p.stock-l.qty);if(p.stock===0)p.avail=false})});
 S.cart=S.cart.filter(c=>c.saved);S.coupon='';S.lastOrders=ids;UI.co=null;save();return ids}
A.place=el=>{if(UI.co.pay==='cod'){createOrders();go('done');return}payFlow()};
function payFlow(){const total=coCalc().reduce((a,c)=>a+c.total,0);sheet(`<div class="state"><div class="ill">⏳</div><h3>${t('Processing payment')}…</h3><p>${t('Please do not close or go back.')} ${inr(total)}</p><div class="progress" style="width:100%"><i style="width:10%" id="pgb"></i></div></div>`,{label:'Payment',nofocus:true});setTimeout(()=>{const b=$('#pgb');if(b)b.style.width='85%'},60);
 setTimeout(()=>{if(S.demo.failPay){S.demo.failPay=false;save();sheet(`<div class="state"><div class="ill">❌</div><h3>${t('Payment failed')}</h3><p>${t('Your money is safe. No order was placed. You can retry or pay on delivery.')}</p><div class="stack" style="width:100%"><button class="btn p block" data-act="retryPay">${ic('refresh',18)} ${t('Retry payment')}</button><button class="btn o block" data-act="payCod">${t('Pay on delivery instead')}</button><button class="btn t" data-act="closeSheet">${t('Cancel')}</button></div></div>`,{label:'Payment failed'})}else{closeSheet();createOrders();go('done')}},1500)}
A.retryPay=()=>payFlow();A.payCod=()=>{closeSheet();UI.co.pay='cod';createOrders();go('done')};
V.done=()=>{const ids=S.lastOrders||[],os=ids.map(order).filter(Boolean);if(!os.length)return empty('🛍️','No recent order','Your placed orders appear here.','<a class="btn p" href="#orders">'+t('My orders')+'</a>');
 return `<div class="stack center" style="max-width:560px;margin:0 auto"><div class="state" style="padding-bottom:0"><div class="ill" style="background:var(--success-soft)">✅</div><h1>${t('Order placed!')}</h1><p>${os.length>1?t('Your order was split into')+' '+os.length+' '+t('shops. Each has its own order ID.'):t('The shop has been notified.')}</p></div>${os.map(o=>`<div class="card pad stack" style="text-align:left"><div class="row between"><b>${esc(nm(biz(o.bid).name))}</b>${stBadge(o.status,o)}</div><div class="row between small"><span>${t('Order ID')}: <b>${o.id}</b></span><b>${inr(orderTotal(o))}</b></div><div class="small t2">${o.mode==='pickup'?t('Self-pickup · code')+' '+o.pickupCode:t('Home delivery · OTP')+' '+o.otp}</div><div class="row"><a class="btn p grow" href="#order-${o.id}">${t('Track order')}</a></div></div>`).join('')}<a class="btn t" href="#home">${t('Continue shopping')}</a></div>`};
