A.addrPick=()=>sheet(`<div class="row between"><h3>${t('Select address')}</h3><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><div class="stack" style="margin-top:10px">${S.addrs.map(a=>`<button class="card pad row" style="text-align:left;${S.selAddr===a.id?'border-color:var(--primary);background:var(--primary-soft)':''}" data-act="addrSel" data-id="${a.id}">${ic('pin',20)}<span class="grow"><b>${esc(a.label)}</b>${a.def?` <span class="badge sec">${t('Default')}</span>`:''}<span class="small t2" style="display:block">${esc(a.line)}, ${esc(areaName(a.area))}</span></span></button>`).join('')}<button class="btn o block" data-act="addrEdit" data-id="">${ic('plus',18)} ${t('Add new address')}</button></div>`);
A.addrSel=el=>{S.selAddr=el.dataset.id;save();closeSheet();render(true)};
let pickLL=null;
A.addrEdit=el=>{const a=S.addrs.find(x=>x.id===el.dataset.id)||{id:'',label:'Home',name:S.user?S.user.name:'',phone:S.user?S.user.phone:'',line:'',landmark:'',pin:'274304',area:'chauraha',lat:S.loc.lat,lng:S.loc.lng,def:!S.addrs.length};pickLL={lat:a.lat,lng:a.lng};
 sheet(`<div class="row between"><h3>${a.id?t('Edit address'):t('Add address')}</h3><button class="iconbtn" data-act="closeSheet" aria-label="${t('Close')}">${ic('x')}</button></div><form data-form="addr" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${a.id}"><input type="hidden" name="lat" id="al" value="${a.lat}"><input type="hidden" name="lng" id="ag" value="${a.lng}">
 <div><div class="lbl small">${t('Drag the pin to your door')}</div>${mapSvg('pickmap',[],{drag:a,noMe:true,center:a})}<div class="small" id="pickinfo"></div></div>
 <div class="chips">${['Home','Work','Other'].map(l=>`<label class="chip"><input type="radio" name="label" value="${l}" ${a.label===l?'checked':''} style="accent-color:var(--primary)"> ${t(l)}</label>`).join('')}</div>
 ${field('Full name','name',a.name,{req:1})}${field('Mobile number','phone',a.phone,{req:1,type:'tel',pattern:'[0-9]{10}',im:'numeric'})}${field('House / street','line',a.line,{req:1})}${field('Landmark','landmark',a.landmark,{ph:'e.g. near Hata Road Chauraha'})}
 <div class="grid g2">${field('PIN code','pin',a.pin,{req:1,pattern:'[0-9]{6}',im:'numeric'})}${field('Area','area',a.area,{type:'select',opts:AREAS.map(x=>[x.id,x.en])})}</div><label class="check"><input type="checkbox" name="def" ${a.def?'checked':''}>${t('Make this my default address')}</label>
 <div class="row">${a.id?`<button type="button" class="btn d grow" data-act="addrDel" data-id="${a.id}">${t('Delete')}</button>`:''}<button class="btn p grow">${t('Save address')}</button></div></form>`,{wide:true});
 attachPicker('pickmap',a,ll=>{pickLL=ll;$('#al').value=ll.lat;$('#ag').value=ll.lng;const d=km(ll,CENTER);$('#pickinfo').innerHTML=d>15?'⚠️ '+t('This pin is outside our service area.'):'✓ '+d.toFixed(1)+' km '+t('from Padrauna centre')});};
function attachPicker(id,center,cb){setTimeout(()=>{const m=$('#'+id);if(!m)return;const svg=m.querySelector('svg'),pin=m.querySelector('#dragpin');let drag=false;const set=e=>{const r=svg.getBoundingClientRect(),x=(e.clientX-r.left)*360/r.width,y=(e.clientY-r.top)*300/r.height;const ll=mapLL(x,y,center);pin.setAttribute('transform',`translate(${clamp(x,8,352)},${clamp(y,36,292)})`);cb(ll)};svg.addEventListener('pointerdown',e=>{drag=true;svg.setPointerCapture(e.pointerId);set(e)});svg.addEventListener('pointermove',e=>{if(drag)set(e)});svg.addEventListener('pointerup',()=>drag=false);cb({lat:center.lat,lng:center.lng})},60)}
F.addr=d=>{let a=S.addrs.find(x=>x.id===d.id);const ob={label:d.label||'Home',name:d.name,phone:d.phone,line:d.line,landmark:d.landmark,pin:d.pin,area:d.area,lat:+d.lat,lng:+d.lng,def:!!d.def};if(km({lat:ob.lat,lng:ob.lng},CENTER)>15){toast(t('This pin is outside our service area.'),'alert');return}
 if(ob.def)S.addrs.forEach(x=>x.def=false);if(a)Object.assign(a,ob);else{a={id:rid('ad'),...ob};S.addrs.push(a)}if(!S.addrs.some(x=>x.def))S.addrs[0].def=true;S.selAddr=a.id;save();closeSheet();render(true);toast(t('Address saved'),'pin')};
A.addrDel=el=>{S.addrs=S.addrs.filter(x=>x.id!==el.dataset.id);if(S.selAddr===el.dataset.id)S.selAddr=S.addrs[0]?S.addrs[0].id:'';save();closeSheet();render(true);toast(t('Address deleted'),'trash')};
V.addresses=()=>{if(!S.user)return V.login();return `<div class="stack"><h1>${t('Saved addresses')}</h1>${S.addrs.length?S.addrs.map(a=>`<div class="card pad row" style="align-items:flex-start">${ic('pin',22)}<div class="grow"><b>${esc(a.label)}</b> ${a.def?`<span class="badge sec">${t('Default')}</span>`:''}<div class="small t2">${esc(a.name)} · ${esc(a.phone)}<br>${esc(a.line)}, ${esc(a.landmark)}, ${esc(areaName(a.area))} ${esc(a.pin)}</div></div><button class="btn t sm" data-act="addrEdit" data-id="${a.id}">${t('Edit')}</button></div>`).join(''):empty('📍','No saved addresses','Add one to get home delivery.')}<button class="btn p" data-act="addrEdit" data-id="">${ic('plus',18)} ${t('Add address')}</button></div>`};
/* ===== ORDERS ===== */
const myOrders=()=>D().orders.filter(o=>o.uid==='u1');
const grp=o=>['delivered','pickedup'].includes(o.status)?'done':['cancelled','refunded'].includes(o.status)?'cancel':'active';
V.orders=()=>{if(!S.user)return `<div class="stack"><h1>${t('My orders')}</h1>${empty('📦','Log in to see your orders','Track orders and reorder in one tap.','<a class="btn p" href="#login" data-act="loginNext">'+t('Log in')+'</a>')}</div>`;const tab=UI.orders,l=myOrders().filter(o=>grp(o)===tab);
 return `<div class="stack"><h1>${t('My orders')}</h1><div class="tabs" role="tablist">${[['active','Active'],['done','Completed'],['cancel','Cancelled']].map(([k,lb])=>`<button role="tab" class="${tab===k?'on':''}" data-act="otab" data-v="${k}">${t(lb)} <span class="cnt" style="background:var(--surface-2);color:var(--text)">${myOrders().filter(o=>grp(o)===k).length}</span></button>`).join('')}</div>${l.length?`<div class="grid auto">${l.map(o=>{const b=biz(o.bid);return `<a class="card pad stack hover" href="#order-${o.id}"><div class="row between"><b>${o.id}</b>${stBadge(o.status,o)}</div><div class="row">${art(b.emoji,b.hue,'mini')}<div class="grow"><b>${esc(nm(b.name))}</b><div class="small t2">${o.items.map(i=>nm(i.name)+' ×'+i.qty).join(', ').slice(0,60)}</div></div></div><div class="row between small"><span>${fdt(o.ts)}</span><b>${inr(orderTotal(o))}</b></div><span class="badge neu" style="justify-self:start">${o.mode==='pickup'?ic('store',13)+' '+t('Self-pickup'):ic('truck',13)+' '+t('Home delivery')}</span></a>`}).join('')}</div>`:empty('📦','No orders here','Your orders will appear here.','<a class="btn p" href="#home">'+t('Start shopping')+'</a>')}</div>`};
A.otab=el=>{UI.orders=el.dataset.v;render(true)};
function timeline(o){const flow=flowOf(o),idx=flow.indexOf(o.status);const cancelled=['cancelled','refunded'].includes(o.status);return `<ol class="tl" style="list-style:none;padding:0;margin:0">${flow.map((s,i)=>{const h=o.history.find(x=>x.s===s);const done=!cancelled&&i<=idx||(cancelled&&h);const curr=!cancelled&&i===idx&&!['delivered','pickedup'].includes(o.status);const lab=(s==='ready'&&o.mode==='pickup')?'Ready for pickup':OST[s][0];return `<li class="s ${done?'done':''} ${curr?'cur':''}"><span class="n">${done?'✓':i+1}</span><div><b>${t(lab)}</b>${h?`<div class="xs muted">${ftime(h.ts)}</div>`:''}</div></li>`}).join('')}${cancelled?`<li class="s done" style="--x:1"><span class="n" style="background:var(--error);border-color:var(--error)">✕</span><div><b>${t('Cancelled')}</b>${o.cancel?`<div class="xs muted">${t('By')} ${t(o.cancel.by)}: ${esc(t(o.cancel.reason))}</div>`:''}</div></li>`:''}</ol>`}
V.order=id=>{const o=order(id);if(!o||(o.uid!=='u1'&&S.role==='customer'))return V.nf();const b=biz(o.bid),job=D().jobs.find(j=>j.oid===o.id),rd=o.riderId?rider(o.riderId):null,tot=orderTotal(o);
 const ob=o.history.find(h=>h.s==='out');
 if(o.status==='out')post.push(()=>{clearInterval(UI.trk);UI.trk=setInterval(()=>{if(cur().raw!=='order-'+id)return clearInterval(UI.trk);render(true)},8000)});
 let track='';
 if(o.mode==='delivery'&&['out'].includes(o.status)&&rd){const pos=o.addrPos||addrPos();const p=clamp((Date.now()-(ob?ob.ts:Date.now()))/(((job&&job.dist)||2)*60000*2),.06,.94);const rp={lat:b.lat+(pos.lat-b.lat)*p,lng:b.lng+(pos.lng-b.lng)*p};const eta=Math.max(2,Math.round(((job&&job.dist)||2)*6*(1-p)));
  track=`<div class="card pad stack"><h3><span class="livedot"></span>${t('Live tracking')}</h3>${alertBox('info',`<b>${t('Arriving in about')} ${eta} ${t('min')}</b>`,'bike')}${mapSvg('trk',[{id:'shop',name:b.name,emoji:'🏪',lat:b.lat,lng:b.lng},{id:'rider',name:{en:'Rider'},emoji:'🛵',lat:rp.lat,lng:rp.lng},{id:'drop',name:{en:'You'},emoji:'🏠',lat:pos.lat,lng:pos.lng}],{center:{lat:(b.lat+pos.lat)/2,lng:(b.lng+pos.lng)/2},noMe:true})}<div class="row"><div class="mini art" style="--h:30">🛵</div><div class="grow"><b>${esc(rd.name)}</b><div class="small t2">${stars(rd.rating)} ${rd.rating} · ${esc(rd.vehicle)}</div></div><a class="btn p sm" href="${telH(rd.phone)}">${ic('phone',16)} ${t('Call')}</a></div><div class="card pad center" style="background:var(--primary-soft)"><div class="small">${t('Share this OTP with the rider only at delivery')}</div><div class="big" style="letter-spacing:.3em">${o.otp}</div></div></div>`}
 else if(o.mode==='delivery'&&!['delivered','cancelled','refunded'].includes(o.status))track=`<div class="card pad center" style="background:var(--primary-soft)"><div class="small">${t('Your delivery OTP')}</div><div class="big" style="letter-spacing:.3em">${o.otp}</div><div class="xs muted">${t('Tell the delivery person at your door')}</div></div>`;
 const pick=o.mode==='pickup'&&!['cancelled','refunded'].includes(o.status)?`<div class="card pad stack"><h3>${t('Self-pickup')}</h3><dl class="kv"><dt>${t('Shop')}</dt><dd>${esc(nm(b.name))}</dd><dt>${t('Address')}</dt><dd>${esc(b.addr)}</dd></dl><div class="small t2">${ic('info',14)} ${esc(b.del.note)}</div>${o.status!=='pickedup'?`<div class="card pad center" style="background:var(--primary-soft)"><div class="small">${t('Pickup code')}</div><div class="big" style="letter-spacing:.3em">${o.pickupCode}</div></div>`:''}<a class="btn o" target="_blank" rel="noopener" href="${mapsDir(b)}">${ic('nav',18)} ${t('Directions')}</a></div>`:'';
 const canCancel=['placed','accepted','preparing'].includes(o.status),canRefund=o.status==='delivered'&&!o.refund,done=['delivered','pickedup'].includes(o.status);
 const refund=o.refund?`<div class="card pad stack"><h3>${t('Refund status')}</h3><ol class="tl" style="list-style:none;padding:0;margin:0">${[['requested','Refund requested'],['approved','Approved by shop/admin'],['completed','Refund completed']].map(([s,l])=>{const st=o.refund.steps.find(x=>x[0]===s);return `<li class="s ${st?'done':''}"><span class="n">${st?'✓':'•'}</span><div><b>${t(l)}</b>${st?`<div class="xs muted">${fdt(st[1]>1e12?st[1]:Date.now()-st[1]*MIN)}</div>`:''}</div></li>`}).join('')}</ol></div>`:'';
 const sub=o.partial?alertBox('warn',`<b>${t('Some items were unavailable')}</b>: ${esc(o.partial)}`):'';
 return `<div class="stack-lg"><button class="btn t sm" data-act="back" style="justify-self:start">${ic('cl',16)} ${t('Back')}</button><div class="row between wrap-r"><div><h1>${t('Order')} ${o.id}</h1><div class="small muted">${fdt(o.ts)}</div></div>${stBadge(o.status,o)}</div>${sub}
 <div class="cols2"><div class="stack"><div class="card pad"><h3 style="margin-bottom:10px">${o.mode==='pickup'?t('Pickup progress'):t('Delivery progress')}</h3>${timeline(o)}</div>${track}${pick}${refund}${o.case?`<div class="card pad stack"><h3>${t('Your request')}</h3><div class="row between"><span>${esc(t(o.case.type))}</span><span class="badge ${o.case.status==='resolved'?'ok':'warn'}">${t(o.case.status==='resolved'?'Resolved':'In review')}</span></div>${(o.case.notes||[]).map(n=>`<div class="small t2">• ${esc(n)}</div>`).join('')}</div>`:''}</div>
 <div class="stack"><div class="card pad stack"><a class="row" href="#biz-${b.id}">${art(b.emoji,b.hue,'mini')}<div class="grow"><b>${esc(nm(b.name))}</b><div class="xs muted">${esc(b.addr)}</div></div>${ic('cr')}</a>${o.items.map(i=>`<div class="row between small"><span>${i.emoji} ${esc(nm(i.name))}${i.variant?' ('+esc(i.variant)+')':''} × ${i.qty}</span><span>${inr(i.price*i.qty)}</span></div>`).join('')}<div class="divider"></div><dl class="kv"><dt>${t('Subtotal')}</dt><dd>${inr(o.subtotal)}</dd>${o.discount?`<dt>${t('Discount')}</dt><dd>−${inr(o.discount)}</dd>`:''}<dt>${t('Delivery')}</dt><dd>${inr(o.delivery)}</dd><dt>${t('Platform fee')}</dt><dd>${inr(o.fee)}</dd><dt><b>${t('Total')}</b></dt><dd><b>${inr(tot)}</b></dd><dt>${t('Payment')}</dt><dd>${esc(o.pay.method)} · ${t(o.pay.status==='paid'?'Paid':o.pay.status==='refunded'?'Refunded':'Pay later')}</dd></dl>${o.addr?`<div class="small t2">${ic('pin',14)} ${esc(o.addr)}</div>`:''}</div>
 <div class="card pad stack"><h3>${t('Need help?')}</h3><div class="grid g2"><a class="btn g sm" href="${telH(b.phone)}">${ic('phone',16)} ${t('Contact shop')}</a>${rd?`<a class="btn g sm" href="${telH(rd.phone)}">${ic('bike',16)} ${t('Contact rider')}</a>`:''}<button class="btn g sm" data-act="reorder" data-id="${o.id}">${ic('refresh',16)} ${t('Reorder')}</button><a class="btn g sm" href="#invoice-${o.id}">${ic('doc',16)} ${t('Invoice')}</a>${canCancel?`<button class="btn d sm" data-act="cancelOrder" data-id="${o.id}">${t('Cancel order')}</button>`:''}${canRefund?`<button class="btn o sm" data-act="refundReq" data-id="${o.id}">${t('Request refund')}</button>`:''}<button class="btn g sm" data-act="problem" data-id="${o.id}">${ic('flag',16)} ${t('Report a problem')}</button></div></div>
 ${done?`<div class="card pad stack"><h3>${t('Rate your experience')}</h3><div class="grid g2"><a class="btn o sm" href="#rev-${o.bid}">${t('Rate shop')}</a>${o.items[0]?`<a class="btn o sm" href="#rev-${o.items[0].pid}">${t('Rate product')}</a>`:''}${o.riderId?`<a class="btn o sm" href="#rev-${o.riderId}">${t('Rate rider')}</a>`:''}</div></div>`:''}</div></div></div>`};
const CANCEL_R=['Ordered by mistake','Found a better price','Delivery is taking too long','Want to change items or address','Other'];
A.cancelOrder=el=>sheet(`<h3>${t('Cancel this order?')}</h3><form data-form="cancel" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${el.dataset.id}"><div role="radiogroup" class="stack" style="gap:6px">${CANCEL_R.map((r,i)=>`<label class="check card pad"><input type="radio" name="reason" value="${r}" ${i?'':'checked'} style="accent-color:var(--primary)">${t(r)}</label>`).join('')}</div><div class="row"><button type="button" class="btn g grow" data-act="closeSheet">${t('Keep order')}</button><button class="btn d grow">${t('Cancel order')}</button></div></form>`);
F.cancel=d=>{const o=order(d.id);o.cancel={by:'customer',reason:d.reason};const paid=o.pay.status==='paid';setStatus(o,'cancelled');o.case={type:'Cancellation',status:'open',notes:['Reason: '+d.reason]};if(paid){o.refund={status:'requested',steps:[['requested',Date.now()]]}}
 notify('vendor','Order '+o.id+' cancelled','Customer cancelled: '+d.reason,'vorder-'+o.id,'order');notify('admin','Cancellation: '+o.id,d.reason+(paid?' · refund due':''),'aorder-'+o.id,'order');save();
 sheet(`<div class="state"><div class="ill">📨</div><h3>${t('Order cancelled')}</h3><p>${t('Admin and vendor have been notified and will contact you to resolve it.')}${paid?' '+t('Your refund has been requested.'):''}</p><button class="btn p" data-act="closeSheet">${t('OK')}</button></div>`);render(true)};
A.refundReq=el=>sheet(`<h3>${t('Request a refund')}</h3><form data-form="refund" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${el.dataset.id}">${field('Reason','reason','',{type:'select',opts:[['Item damaged','Item damaged'],['Wrong item','Wrong item'],['Item missing','Item missing'],['Quality issue','Quality issue'],['Other','Other']]})}${field('Details','d','',{type:'textarea'})}${uploader('Add a photo (optional)')}<button class="btn p">${t('Submit request')}</button></form>`);
F.refund=d=>{const o=order(d.id);o.refund={status:'requested',reason:d.reason,steps:[['requested',Date.now()]]};o.case={type:'Refund',status:'open',notes:[d.reason+(d.d?': '+d.d:'')]};notify('vendor','Refund requested '+o.id,d.reason,'vorder-'+o.id,'order');notify('admin','Refund case '+o.id,d.reason,'aorder-'+o.id,'order');save();closeSheet();sheet(`<div class="state"><div class="ill">📨</div><h3>${t('Refund requested')}</h3><p>${t('Admin and vendor have been notified and will contact you to resolve it.')}</p><button class="btn p" data-act="closeSheet">${t('OK')}</button></div>`);render(true)};
A.problem=el=>sheet(`<h3>${t('Report a problem')}</h3><form data-form="prob" class="stack" style="margin-top:10px"><input type="hidden" name="id" value="${el.dataset.id}">${field('What happened?','reason','',{type:'select',opts:[['Late delivery','Late delivery'],['Rude behaviour','Rude behaviour'],['Wrong amount charged','Wrong amount charged'],['Item unavailable / substituted','Item unavailable / substituted'],['Other','Other']]})}${field('Details','d','',{type:'textarea'})}<button class="btn p">${t('Submit')}</button></form>`);
F.prob=d=>{const o=order(d.id);o.case={type:'Problem',status:'open',notes:[d.reason+(d.d?': '+d.d:'')]};notify('admin','Problem reported '+o.id,d.reason,'aorder-'+o.id,'order');notify('vendor','Problem reported '+o.id,d.reason,'vorder-'+o.id,'order');save();closeSheet();toast(t('Reported. We will contact you.'),'flag');render(true)};
A.reorder=el=>{const o=order(el.dataset.id);let n=0;o.items.forEach(i=>{if(addToCart(i.pid,i.qty,i.variant))n++});if(n){toast(t('Items added to cart'),'cart');go('cart')}};
V.invoice=id=>{const o=order(id);if(!o)return V.nf();const b=biz(o.bid);return `<div class="stack"><div class="row noprint"><button class="btn t sm" data-act="back">${ic('cl',16)} ${t('Back')}</button><span class="grow"></span><button class="btn p sm" onclick="window.print()">${ic('print',16)} ${t('Print / Save PDF')}</button></div><div class="card pad stack" style="max-width:640px;margin:0 auto;width:100%"><div class="row between"><div><h2>${t('Tax invoice')}</h2><div class="small muted">${o.id} · ${fdate(o.ts)}</div></div>${logoHtml}</div><div class="divider"></div><div class="grid g2 small"><div><b>${esc(nm(b.name))}</b><br>${esc(b.addr)}<br>+91 ${b.phone}</div><div><b>${esc(o.cust)}</b><br>${esc(o.addr||t('Self-pickup'))}<br>+91 ${esc(o.phone)}</div></div>${tbl(['Item','Qty','Price','Amount'],o.items.map(i=>[esc(nm(i.name)),i.qty,inr(i.price),inr(i.price*i.qty)]))}<dl class="kv"><dt>${t('Subtotal')}</dt><dd>${inr(o.subtotal)}</dd><dt>${t('Discount')}</dt><dd>−${inr(o.discount)}</dd><dt>${t('Delivery')}</dt><dd>${inr(o.delivery)}</dd><dt>${t('Platform fee')}</dt><dd>${inr(o.fee)}</dd><dt><b>${t('Total')}</b></dt><dd><b>${inr(orderTotal(o))}</b></dd></dl><div class="xs muted">${t('GST included in item prices. This is a sample invoice.')}</div></div></div>`};
